/**
 * Color Settings module - custom color overrides per theme
 */
(() => {
    const STORAGE_KEY = 'slippy-custom-colors';
    function loadColors() { try { const stored = localStorage.getItem(STORAGE_KEY); return stored ? JSON.parse(stored) : {}; } catch { return {}; } }
    function saveColors(colors) { try { localStorage.setItem(STORAGE_KEY, JSON.stringify(colors)); } catch { console.warn('Failed to save custom colors'); } }
    function getColors(theme) { const all = loadColors(); return all[theme] || {}; }
    function applyColors(theme) { const colors = getColors(theme); const styleId = 'custom-colors'; let styleEl = document.getElementById(styleId); if (!styleEl) { styleEl = document.createElement('style'); styleEl.id = styleId; document.head.appendChild(styleEl); } const entries = Object.entries(colors); if (entries.length === 0) { styleEl.textContent = ''; return; } let css = ''; entries.forEach(([varName, value]) => { css += `${varName}: ${value}; `; if (varName === '--accent') { const rgb = hexToRgb(value); if (rgb) css += `--accent-rgb: ${rgb.r}, ${rgb.g}, ${rgb.b}; `; } }); styleEl.textContent = `.theme-${theme} { ${css} }`; }
    function clearColors() { const styleEl = document.getElementById('custom-colors'); if (styleEl) styleEl.textContent = ''; }
    let previewColors = {};
    function preview(varName, value) { previewColors[varName] = value; const theme = document.body.classList.contains('theme-light') ? 'light' : 'dark'; const styleId = 'custom-colors-preview'; let styleEl = document.getElementById(styleId); if (!styleEl) { styleEl = document.createElement('style'); styleEl.id = styleId; document.head.appendChild(styleEl); } let css = ''; Object.entries(previewColors).forEach(([name, val]) => { css += `${name}: ${val}; `; if (name === '--accent') { const rgb = hexToRgb(val); if (rgb) css += `--accent-rgb: ${rgb.r}, ${rgb.g}, ${rgb.b}; `; } }); styleEl.textContent = `.theme-${theme} { ${css} }`; }
    function clearPreview() { previewColors = {}; const styleEl = document.getElementById('custom-colors-preview'); if (styleEl) styleEl.textContent = ''; }
    function save(theme, colors) { clearPreview(); const all = loadColors(); all[theme] = colors; saveColors(all); applyColors(theme); }
    function reset(theme) { clearPreview(); clearColors(); const all = loadColors(); delete all[theme]; saveColors(all); }
    function hexToRgb(hex) { const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex); return result ? { r: parseInt(result[1], 16), g: parseInt(result[2], 16), b: parseInt(result[3], 16) } : null; }
    function init() { const observer = new MutationObserver(() => { const theme = document.body.classList.contains('theme-light') ? 'light' : 'dark'; applyColors(theme); }); observer.observe(document.body, { attributes: true, attributeFilter: ['class'] }); const initialTheme = document.body.classList.contains('theme-light') ? 'light' : 'dark'; applyColors(initialTheme); }
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
    window.ColorSettings = { getColors, preview, clearPreview, save, reset, applyColors };
})();
